"""Small resilient client for the order service.

- fetches a token lazily and replaces it whenever the service rejects it
- on 429 waits as long as the service says (Retry-After header / retry_after body)
- repeats any other failed request (5xx, network errors, malformed bodies)
- logs every non-200 response in full to events.log so unexpected behaviour is visible
"""
import json
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"
LOGPATH = "/tmp/recon/events.log"


def _log(**kw):
    kw["t"] = time.strftime("%H:%M:%S")
    with open(LOGPATH, "a") as f:
        f.write(json.dumps(kw) + "\n")


class NotFound(Exception):
    pass


class Client:
    def __init__(self):
        self.token = None
        self.stats = {"requests": 0, "ok": 0, "429": 0, "401/403": 0, "404": 0,
                      "other_err": 0, "tokens": 0, "waited_s": 0.0}

    # -- low level -------------------------------------------------------
    def _raw(self, method, path, use_token):
        headers = {}
        if use_token and self.token:
            headers["Authorization"] = "Bearer " + self.token
        req = urllib.request.Request(
            BASE + path, method=method, headers=headers,
            data=b"" if method == "POST" else None,
        )
        self.stats["requests"] += 1
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return r.status, dict(r.headers), r.read()
        except urllib.error.HTTPError as e:
            return e.code, dict(e.headers), e.read()
        except (urllib.error.URLError, TimeoutError, ConnectionError, OSError) as e:
            return None, {}, ("network error: %r" % (e,)).encode()

    @staticmethod
    def _retry_after(hdrs, body):
        waits = []
        for k, v in hdrs.items():
            if k.lower() == "retry-after":
                try:
                    waits.append(float(v))
                except ValueError:
                    pass
        try:
            j = json.loads(body)
            if isinstance(j, dict) and isinstance(j.get("retry_after"), (int, float)):
                waits.append(float(j["retry_after"]))
        except Exception:
            pass
        return max(waits) if waits else 1.0

    def _sleep(self, secs):
        secs = max(secs, 0.0) + 0.1
        self.stats["waited_s"] += secs
        time.sleep(secs)

    # -- token -----------------------------------------------------------
    def new_token(self, max_attempts=200):
        for attempt in range(1, max_attempts + 1):
            status, hdrs, body = self._raw("POST", "/token", False)
            if status == 200:
                try:
                    tok = json.loads(body)["token"]
                    if isinstance(tok, str) and tok:
                        self.token = tok
                        self.stats["tokens"] += 1
                        return tok
                except Exception:
                    pass
            _log(kind="token_fail", status=status, headers=hdrs,
                 body=body[:500].decode("utf-8", "replace"))
            if status == 429:
                self.stats["429"] += 1
                self._sleep(self._retry_after(hdrs, body))
            else:
                self.stats["other_err"] += 1
                self._sleep(1.0)
        raise RuntimeError("could not obtain a token")

    # -- authenticated GET -----------------------------------------------
    def get(self, path, validate=None, max_attempts=400, not_found_confirmations=3):
        """GET path as JSON. `validate(obj)` must return True for an acceptable body.
        Raises NotFound only after the 404 has been confirmed several times."""
        not_found_seen = 0
        for attempt in range(1, max_attempts + 1):
            if self.token is None:
                self.new_token()
            status, hdrs, body = self._raw("GET", path, True)
            if status == 200:
                try:
                    obj = json.loads(body)
                    if validate is None or validate(obj):
                        self.stats["ok"] += 1
                        return obj
                    _log(kind="invalid_body", path=path, status=status,
                         body=body[:500].decode("utf-8", "replace"))
                except Exception as e:
                    _log(kind="unparseable_body", path=path, status=status, err=repr(e),
                         body=body[:500].decode("utf-8", "replace"))
                self.stats["other_err"] += 1
                self._sleep(0.5)
                continue

            _log(kind="non200", path=path, status=status, attempt=attempt,
                 headers=hdrs, body=body[:500].decode("utf-8", "replace"))
            if status == 429:
                self.stats["429"] += 1
                self._sleep(self._retry_after(hdrs, body))
            elif status in (401, 403):
                self.stats["401/403"] += 1
                self.token = None          # fetch a fresh one on the next loop
            elif status == 404:
                self.stats["404"] += 1
                not_found_seen += 1
                if not_found_seen >= not_found_confirmations:
                    raise NotFound(path)
                self._sleep(0.5)
            else:
                self.stats["other_err"] += 1
                self._sleep(1.0)
        raise RuntimeError("giving up on %s after %d attempts" % (path, max_attempts))

