"""Shared helpers: loading stored order pages, UTC conversion, qualification, rounding."""
import datetime as dt
import glob
import json

START = dt.datetime(2025, 3, 1, 0, 0, 0, tzinfo=dt.timezone.utc)   # inclusive
END = dt.datetime(2025, 6, 1, 0, 0, 0, tzinfo=dt.timezone.utc)     # exclusive (== through 31 May 23:59:59)


def load_listings(d):
    """All listed orders, in page order, duplicates included."""
    out = []
    for path in sorted(glob.glob(d + "/orders_page_*.json")):
        out.extend(json.load(open(path))["items"])
    return out


def dedupe(listings):
    """-> (dict id -> order, number of repeated listings discarded). Repeats must be identical."""
    seen, dups = {}, 0
    for o in listings:
        if o["id"] in seen:
            dups += 1
            if seen[o["id"]] != o:
                raise ValueError("repeated listing differs for " + o["id"])
        else:
            seen[o["id"]] = o
    return seen, dups


def parse_utc(s):
    t = dt.datetime.fromisoformat(s)           # python 3.11: handles 'Z' and +hh:mm offsets
    if t.tzinfo is None:
        raise ValueError("timestamp without offset: " + s)
    return t.astimezone(dt.timezone.utc)


def qualifies(o):
    return o["status"] == "shipped" and START <= parse_utc(o["placed_at"]) < END


def discounted_cents(amount_cents, discount_pct):
